"""Base scenario adapter and result abstractions for offensive testing."""

import logging
import time
from abc import ABC, abstractmethod
from dataclasses import dataclass
from datetime import UTC, datetime

from app.engine.evidence import build_evidence
from app.engine.semantics import ErrorCategory, ResultOutcome
from app.models.lab import LabTarget

logger = logging.getLogger("vadl.engine.adapters")


@dataclass
class AdapterResult:
    """Standardized test result generated by a scenario adapter."""

    scenario_id: str
    test_identifier: str
    target_edition: str  # "vulnerable" or "secure"
    outcome: ResultOutcome
    error_category: ErrorCategory | None
    evidence: str
    started_at: datetime
    completed_at: datetime
    duration_ms: int


class BaseScenarioAdapter(ABC):
    """Abstract base class for scenario-specific offensive testing adapters."""

    scenario_id: str = ""

    def execute(
        self,
        target: LabTarget,
        edition: str,
        client,
        timeout_seconds: int = 5,
        max_evidence_bytes: int = 4096,
    ) -> AdapterResult:
        """Execute a controlled test case with bounded runtime and exception isolation."""
        test_id = f"{self.scenario_id}_{edition.upper()}_{int(time.time())}"
        started_at = datetime.now(UTC)
        start_mono = time.monotonic()

        try:
            # Delegate to scenario-specific test logic
            outcome, err_cat, evidence = self._run_test(
                target=target,
                edition=edition,
                client=client,
                test_identifier=test_id,
                timeout_seconds=timeout_seconds,
                max_evidence_bytes=max_evidence_bytes,
            )
        except TimeoutError as exc:
            logger.warning(f"Adapter timeout for {self.scenario_id} [{edition}]: {exc}")
            outcome = ResultOutcome.ERROR
            err_cat = ErrorCategory.TIMEOUT
            evidence = build_evidence(
                scenario_id=self.scenario_id,
                test_identifier=test_id,
                target_edition=edition,
                request_method="N/A",
                request_url=target.base_url,
                expected_behavior="Response within timeout",
                observed_behavior=f"Execution timed out after {timeout_seconds}s",
                rationale="Test aborted due to execution timeout limit.",
                max_bytes=max_evidence_bytes,
            )
        except Exception as exc:
            logger.exception(
                f"Unhandled exception in adapter {self.scenario_id} [{edition}]: {exc}"
            )
            outcome = ResultOutcome.ERROR
            err_cat = ErrorCategory.EXECUTION_FAULT
            evidence = build_evidence(
                scenario_id=self.scenario_id,
                test_identifier=test_id,
                target_edition=edition,
                request_method="N/A",
                request_url=target.base_url,
                expected_behavior="Successful test execution",
                observed_behavior=f"Adapter error: {type(exc).__name__}: {str(exc)[:200]}",
                rationale="Test encountered an unexpected internal error.",
                max_bytes=max_evidence_bytes,
            )

        completed_at = datetime.now(UTC)
        duration_ms = int((time.monotonic() - start_mono) * 1000)

        return AdapterResult(
            scenario_id=self.scenario_id,
            test_identifier=test_id,
            target_edition=edition,
            outcome=outcome,
            error_category=err_cat,
            evidence=evidence,
            started_at=started_at,
            completed_at=completed_at,
            duration_ms=duration_ms,
        )

    @abstractmethod
    def _run_test(
        self,
        target: LabTarget,
        edition: str,
        client,
        test_identifier: str,
        timeout_seconds: int,
        max_evidence_bytes: int,
    ) -> tuple[ResultOutcome, ErrorCategory | None, str]:
        """Implement scenario-specific offensive testing routine."""
        raise NotImplementedError
